            try:

                try:
                    url = get_model_url(
                        instance, kind="edit", user=request.user, shop=get_shop(request), raise_permission_denied=True
                    )
                except NoModelUrl:

                    try:
                        url = get_model_url(
                            instance,
                            kind="detail",
                            user=request.user,
                            shop=get_shop(request),
