def do_format_lastupdated(value, now=None):
    """
    Used to format date as "Updated 10 minutes ago".

    Value could be a RdiffTime or an epoch as int.
    """
    if not value:
        return ""
    now = librdiff.RdiffTime(now)
    delta = now.epoch() - (value.epoch() if isinstance(value, librdiff.RdiffTime) else value)
    delta = datetime.timedelta(seconds=delta)
    if delta.days > 365:
        return _('%d years ago') % (delta.days / 365)
    if delta.days > 60:
        return _('%d months ago') % (delta.days / 30)
    if delta.days > 7:
        return _('%d weeks ago') % (delta.days / 7)
    elif delta.days > 1:
        return _('%d days ago') % delta.days
    elif delta.seconds > 3600:
        return _('%d hours ago') % (delta.seconds / 3600)
    elif delta.seconds > 60:
        return _('%d minutes ago') % (delta.seconds / 60)
    return _('%d seconds ago') % delta.seconds
class RdiffRepo(object):
    def __init__(self, user_root, path, encoding):
        if isinstance(user_root, str):
            user_root = os.fsencode(user_root)
        if isinstance(path, str):
            path = os.fsencode(path)
        assert isinstance(user_root, bytes)
        assert isinstance(path, bytes)
        assert encoding
        self._encoding = encodings.search_function(encoding)
        assert self._encoding
        self.path = path.strip(b"/")
        if self.path:
            self.full_path = os.path.normpath(os.path.join(user_root, self.path))
        else:
            self.full_path = os.path.normpath(user_root)


        self._data_path = os.path.join(self.full_path, RDIFF_BACKUP_DATA)
        assert isinstance(self._data_path, bytes)
        self._increment_path = os.path.join(self._data_path, INCREMENTS)
        self.current_mirror = MetadataDict(self, CurrentMirrorEntry)
        self.error_log = MetadataDict(self, LogEntry)
        self.mirror_metadata = MetadataDict(self, MirrorMetadataEntry)
        self.file_statistics = MetadataDict(self, FileStatisticsEntry)
        self.session_statistics = MetadataDict(self, SessionStatisticsEntry)
    def backup_dates(self):
        """Return a list of dates when backup was executed. This list is
        sorted from old to new (ascending order). To identify dates,
        'mirror_metadata' file located in rdiff-backup-data are used."""
        return self.mirror_metadata.keys()
    def backup_log(self):
        """
        Return the location of the backup log.
        """
        return BackupLogEntry(self, b'backup.log')
    def delete(self, path):
        """
        Delete this entry from the repository history using rdiff-backup-delete.
        """
        path_obj = self.fstat(path)
        if path_obj.isroot:
            return self.delete_repo()

        rdiff_backup_delete = find_rdiff_backup_delete()
        cmdline = [rdiff_backup_delete, path_obj.full_path]
        logger.info('executing: %r' % cmdline)
        process = subprocess.Popen(cmdline, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env={'LANG': LANG})
        for line in process.stdout:
            line = line.rstrip(b'\n').decode('utf-8', errors='replace')
            logger.info('rdiff-backup-delete: %s' % line)
        retcode = process.wait()
        if retcode:
            raise CalledProcessError(retcode, cmdline)
    def delete_repo(self):
        """Delete the repository permanently."""


        def handle_error(func, path, exc_info):
            if exc_info[0] == PermissionError:

                if not os.access(os.path.dirname(path), os.W_OK | os.R_OK | os.X_OK):
                    os.chmod(os.path.dirname(path), 0o0700)
                if not os.access(path, os.W_OK | os.R_OK):
                    os.chmod(path, 0o0600)
                if os.path.isdir(path):
                    return shutil.rmtree(path, onerror=handle_error)
                else:
                    return os.unlink(path)
            raise

        try:
            shutil.rmtree(self.full_path, onerror=handle_error)
        except Exception:
            logger.warning('fail to delete repo', exc_info=1)
    def display_name(self):
        """Return the most human representation of the repository name."""
        return self.get_display_name(b'')
    def _decode(self, value, errors='replace'):
        """Used to decode a repository path into unicode."""
        assert isinstance(value, bytes)
        return self._encoding.decode(value, errors)[0]
    def _entries(self):
        return sorted(os.listdir(self._data_path))
    def fstat(self, path):
        """Return a new instance of DirEntry to represent the given path."""

        assert isinstance(path, bytes)
        full_path = os.path.normpath(os.path.join(self.full_path, path.strip(b'/')))
        increment_path = os.path.normpath(os.path.join(self._increment_path, path.strip(b'/'), b'..'))
        if not full_path.startswith(self.full_path) or not increment_path.startswith(self.full_path):
            raise AccessDeniedError('%s make reference outside the repository' % self._decode(path))
        relative_path = os.path.relpath(full_path, self.full_path)
        if relative_path.startswith(RDIFF_BACKUP_DATA):
            raise DoesNotExistError(path)

        if relative_path == b'.':
            return RdiffDirEntry(self, b'', True, [])


        try:
            os.lstat(full_path)
            exists = True
        except (OSError, ValueError):
            exists = False


        increment_items = os.listdir(increment_path)


        prefix = os.path.basename(full_path)
        entry = RdiffDirEntry(self, relative_path, exists, [])
        for item in increment_items:
            if not item.startswith(prefix):

                continue
            try:
                increment = IncrementEntry(item)
            except ValueError:

                continue
            if increment.name != prefix:

                continue

            bisect.insort_left(entry._increments, increment)


        if not exists and not entry._increments:
            logger.error("path [%r] doesn't exists", path)
            raise DoesNotExistError(path)


        return entry
    def last_backup_date(self):
        """Return the last known backup dates."""
        try:
            if len(self.current_mirror) > 0:
                return self.current_mirror[-1].date
            return None
        except (PermissionError, FileNotFoundError):
            return None
    def get_display_name(self, path):
        """
        Return proper display name of the given path according to repository encoding and quoted characters.
        """
        assert isinstance(path, bytes)
        path = path.strip(b'/')
        if path in [b'.', b'']:

            if not self.path:
                return self._decode(unquote(os.path.basename(self.full_path)))
            return self._decode(unquote(self.path))
        else:

            return self._decode(unquote(os.path.basename(path)))
    def remove_older(self, remove_older_than):
        logger.info("execute rdiff-backup --force --remove-older-than=%sD %r", remove_older_than, self.full_path)
        subprocess.call(
            [
                b'rdiff-backup',
                b'--force',
                b'--remove-older-than=' + str(remove_older_than).encode(encoding='latin1') + b'D',
                self.full_path,
            ]
        )
    def restore(self, path, restore_as_of, kind=None):
        """
        Restore the current directory entry into a fileobj containing the
        file content of the directory compressed into an archive.

        `kind` must be one of the supported archive type or none to use `zip` for folder and `raw` for file.

        Return a filename and a fileobj.
        """
        assert isinstance(path, bytes)
        assert restore_as_of, "restore_as_of must be defined"
        assert kind in ['tar', 'tar.bz2', 'tar.gz', 'tbz2', 'tgz', 'zip', 'raw', None]


        path_obj = self.fstat(path)
        if path_obj.isdir:
            if kind == 'raw':
                raise ValueError('raw type not supported for directory')
            kind = kind or 'zip'
        else:
            kind = kind or 'raw'


        if kind == 'raw':
            filename = path_obj.display_name
        else:
            filename = "%s.%s" % (path_obj.display_name, kind)



        cmdline = [
            os.fsencode(sys.executable),
            b'-m',
            b'rdiffweb.core.restore',
            b'--restore-as-of',
            str(restore_as_of).encode('latin'),
            b'--encoding',
            self._encoding.name.encode('latin'),
            b'--kind',
            kind.encode('latin'),
            os.path.join(self.full_path, unquote(path_obj.path)),
            b'-',
        ]
        proc = subprocess.Popen(
            cmdline,
            shell=False,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=None,
        )


        output = b''
        success = False
        line = proc.stderr.readline()
        while line:
            output += line
            if b'Starting restore of' in line:
                success = True
                break
            line = proc.stderr.readline()
        if not success:
            raise CalledProcessError(1, cmdline, output)

        t = threading.Thread(target=_readerthread, args=(proc.stderr, logger.debug))
        t.daemon = True
        t.start()
        return filename, _wrap_close(proc.stdout, proc)
    def restore_log(self):
        """
        Return the location of the restore log.
        """
        return RestoreLogEntry(self, b'restore.log')
    def status(self):
        """Check if a backup is in progress for the current repo."""


        try:

            for current_mirror in self.current_mirror:
                pid = current_mirror.extract_pid()
                try:
                    p = psutil.Process(pid)
                    if any('rdiff-backup' in c for c in p.cmdline()):
                        return ('in_progress', _('A backup is currently in progress to this repository.'))
                except psutil.NoSuchProcess:
                    logger.debug('pid [%s] does not exists', pid)




            if len(self.current_mirror) > 1 or len(self.current_mirror) == 0:
                self._status = ('interrupted', _('The previous backup seams to have failed.'))
                return self._status
        except FileNotFoundError:
            self._entries = []
            return ('failed', _('The repository cannot be found or is badly damaged.'))
        except PermissionError:
            self._entries = []
            logger.warning('error reading current_mirror files', exc_info=1)
            return ('failed', _("Permissions denied. Contact administrator to check repository's permissions."))

        return ('ok', '')
SEP = b'/'
class DuplicateSSHKeyError(Exception):
class UserObject(object):
    def __init__(self, store, data):
        """
        Create a new UserObject from a username or a record.

        `data` a dict or a SQLAlchemy row.

        """
        assert store
        assert 'userid' in data
        self._store = store
        self._record = {k: data[k] for k in self._ATTRS}
        self._userid = data[_USERS.c.userid]
    def add_authorizedkey(self, key, comment=None):
        """
        Add the given key to the user. Adding the key to his `authorized_keys`
        file if it exists and adding it to database.
        """

        assert key
        key = authorizedkeys.check_publickey(key)


        key = authorizedkeys.AuthorizedKey(
            options=None, keytype=key.keytype, key=key.key, comment=comment or key.comment
        )


        filename = os.path.join(self.user_root, '.ssh', 'authorized_keys')
        if os.path.isfile(filename):
            with open(filename, mode="r+", encoding='utf-8') as fh:
                if authorizedkeys.exists(fh, key):
                    raise DuplicateSSHKeyError(_("SSH key already exists"))
                logger.info("add key [%s] to [%s] authorized_keys", key, self.username)
                authorizedkeys.add(fh, key)
        else:

            logger.info("add key [%s] to [%s] database", key, self.username)
            try:
                with self._store.engine.connect() as conn:
                    conn.execute(
                        _SSHKEYS.insert().values(userid=self._userid, fingerprint=key.fingerprint, key=key.getvalue())
                    )
            except IntegrityError:
                raise DuplicateSSHKeyError(
                    _("Duplicate key. This key already exists or is associated to another user.")
                )
        self._store.bus.publish('user_attr_changed', self, {'authorizedkeys': True})
    def valid_user_root(self):
        """
        Check if the current user_root is valid and readable
        """
        try:
            return os.access(self.user_root, os.F_OK) and os.path.isdir(self.user_root)
        except Exception:
            return False
    def delete(self):
        """
        Delete the given user from password store.

        Return True if the user was deleted.
        Return False if the user didn't exists.
        Raise a ValueError when trying to delete the admin user.
        """

        if self.username == self._store._admin_user:
            raise ValueError(_("can't delete admin user"))


        logger.info("deleting user [%s] from database", self.username)
        with self._store.engine.connect() as conn:
            conn.execute(_SSHKEYS.delete(_SSHKEYS.c.userid == self._userid))
            conn.execute(_REPOS.delete(_REPOS.c.userid == self._userid))
            deleted = conn.execute(_USERS.delete(_USERS.c.userid == self._userid))
            assert deleted.rowcount, 'fail to delete user'
        self._store.bus.publish('user_deleted', self.username)
        return True
    def delete_authorizedkey(self, fingerprint):
        """
        Remove the given key from the user. Remove the key from his
        `authorized_keys` file if it exists and from database database.
        """

        filename = os.path.join(self.user_root, '.ssh', 'authorized_keys')
        if os.path.isfile(filename):
            with open(filename, mode='r+', encoding='utf-8') as fh:
                logger.info("removing key [%s] from [%s] authorized_keys", fingerprint, self.username)
                authorizedkeys.remove(fh, fingerprint)
        else:

            logger.info("removing key [%s] from [%s] database", fingerprint, self.username)
            with self._store.engine.connect() as conn:
                conn.execute(
                    _SSHKEYS.delete(and_(_SSHKEYS.c.userid == self._userid, _SSHKEYS.c.fingerprint == fingerprint))
                )
        self._store.bus.publish('user_attr_changed', self, {'authorizedkeys': True})
    def disk_usage(self):

        if not self.user_root or not os.path.exists(self.user_root):
            return 0
        values = self._store.bus.publish('get_disk_usage', self)

        return next((v for v in values if v is not None), 0)
    def disk_quota(self):

        if not self.user_root or not os.path.exists(self.user_root):
            return 0
        values = self._store.bus.publish('get_disk_quota', self)

        return next((v for v in values if v is not None), 0)
    def disk_quota(self, value):

        if not self.user_root or not os.path.exists(self.user_root):
            return
        self._store.bus.publish('set_disk_quota', self, value)
    def __eq__(self, other):
        return isinstance(other, UserObject) and self._userid == other._userid
    def __str__(self):
        return 'UserObject(%s)' % self._userid
    def _get_attr(self, key):
        """Return user's attribute"""
        assert key in self._ATTRS, "invalid attribute: " + key
        return self._record[key]
    def _get_authorizedkeys(self):
        """
        Return an iterator on the authorized key. Either from his
        `authorized_keys` file if it exists or from database.
        """

        filename = os.path.join(self.user_root, '.ssh', 'authorized_keys')
        if os.path.isfile(filename):
            for k in authorizedkeys.read(filename):
                yield k


        with self._store.engine.connect() as conn:
            result = conn.execute(_SSHKEYS.select(_SSHKEYS.c.userid == self._userid))
            for record in result:
                yield authorizedkeys.check_publickey(record['key'])
    def get_repo(self, repopath, refresh=False):
        """
        Return a repo object.
        """
        assert isinstance(repopath, bytes) or isinstance(repopath, str)
        if isinstance(repopath, bytes):
            repopath = os.fsdecode(repopath)
        repopath = repopath.strip('/')

        if refresh:
            self.refresh_repos()


        with self._store.engine.connect() as conn:
            result = conn.execute(_REPOS.select(and_(_REPOS.c.userid == self.userid, _REPOS.c.repopath == repopath)))
            record = result.fetchone()
        if record:
            return RepoObject(self, record)

        raise DoesNotExistError(self.userid, repopath)
    def get_repo_objs(self, refresh=False):
        """
        Return list of repository object.
        """
        if refresh:
            self.refresh_repos()
        with self._store.engine.connect() as conn:
            records = conn.execute(_REPOS.select(_REPOS.c.userid == self._userid).order_by(_REPOS.c.repopath))
            return [RepoObject(self, record) for record in records]
    def refresh_repos(self, delete=False):
        """
        Return list of repositories object to reflect the filesystem folders.

        Return a RepoObject for each sub directories under `user_root` with `rdiff-backup-data`.
        """

        with self._store.engine.connect() as conn:


            def _onerror(unused):
                logger.error('error updating user [%s] repos' % self.username, exc_info=1)

            dirty = False
            records = list(conn.execute(_REPOS.select(_REPOS.c.userid == self._userid).order_by(_REPOS.c.repopath)))
            user_root = os.fsencode(self.user_root)
            for root, dirs, unused_files in os.walk(user_root, _onerror):
                for name in dirs.copy():
                    if name.startswith(b'.'):
                        dirs.remove(name)
                if b'rdiff-backup-data' in dirs:
                    repopath = os.path.relpath(root, start=user_root)
                    del dirs[:]


                    repopath = b'' if repopath == b'.' else repopath


                    record_match = next(
                        (record for record in records if record['repopath'] == os.fsdecode(repopath)), None
                    )
                    if not record_match:

                        conn.execute(_REPOS.insert().values(userid=self._userid, repopath=os.fsdecode(repopath)))
                        dirty = True
                    else:
                        records.remove(record_match)
                if root.count(SEP) - user_root.count(SEP) >= self._store._max_depth:
                    del dirs[:]

            if delete:
                for record in records:
                    conn.execute(_REPOS.delete(_REPOS.c.repoid == record['repoid']))
        return dirty
    def is_ldap(self):
        """Return True if this user is an LDAP user. (with a password)"""
        return not self._get_attr('password')
    def _is_role(self, role):
        assert role in ROLES.values()
        try:
            return int(self._get_attr('role')) <= role
        except ValueError:
            return False
    def _set_attr(self, key, new_value, notify=True):
        """Used to define an attribute"""
        assert key in self._ATTRS, "invalid attribute: " + key

        if self._record[key] == new_value:
            return

        with self._store.engine.connect() as conn:
            updated = conn.execute(_USERS.update().where(_USERS.c.userid == self._userid).values(**{key: new_value}))
            assert updated.rowcount
        old_value = self._record[key]
        self._record[key] = new_value

        if notify:
            self._store.bus.publish('user_attr_changed', self, {key: (old_value, new_value)})
    def set_password(self, password, old_password=None):
        """
        Change the user's password. Raise a ValueError if the username or
        the password are invalid.
        """
        assert isinstance(password, str)
        assert old_password is None or isinstance(old_password, str)
        if not password:
            raise ValueError("password can't be empty")
        cfg = self._store.app.cfg
        if cfg.password_min_length > len(password) > cfg.password_max_length:
            raise ValueError("invalid password length")


        if self.username == self._store._admin_user and self._store._admin_password:
            raise ValueError(_("can't update admin-password defined in configuration file"))

        if old_password and not check_password(old_password, self.hash_password):
            raise ValueError(_("Wrong password"))

        logger.info("updating user password [%s]", self.username)
        self.hash_password = hash_password(password)
        self._store.bus.publish('user_password_changed', self)
    def _set_user_root(self, value):
        """
        Used to take care of updating the user_root.

        When user_root get update, we also want to update the repository list
        to reflect the filesystem.
        """

        self._set_attr('user_root', value)

        self.refresh_repos()
