                if cdt["name"] in new_cols
                else cdt
                for cdt in curr_dtypes
            ]
        else:
            curr_dtypes += [dtype_f(len(curr_dtypes), new_col) for new_col in new_cols]
        global_state.set_dtypes(data_id, curr_dtypes)
