                        extract_ok = True
                        command_line = ''

                    binwalk.core.common.debug("Ran extraction command: %s" % command_line)
                    binwalk.core.common.debug("Extraction successful: %s" % extract_ok)




                    if self.remove_after_execute and (extract_ok == True or i == (len(rules) - 1)):



