        Read null.

        @return: C{None}
        @rtype: C{None}
        """
        return None
    def readBoolFalse(self):
        """
        Returns C{False}.

        @return: C{False}
        @rtype: C{bool}
        """
        return False
    def readBoolTrue(self):
