def unescape_cookie(orig: str) -> str:

    ret = ""
    esc = ""
    for ch in orig:
        if ch == "%":
            if len(esc) > 0:
                ret += esc
            esc = ch

        elif len(esc) > 0:
            esc += ch
            if len(esc) == 3:
                try:
                    ret += chr(int(esc[1:], 16))
                except:
                    ret += esc
                esc = ""

        else:
            ret += ch

    if len(esc) > 0:
        ret += esc

    return ret
