            orig_path = path

            parts = path.split('/')

            if not cm.file_exists(path=path) and 'files' in parts:


                self.log.warn("Deprecated files/ URL: %s", orig_path)
                parts.remove('files')
                path = '/'.join(parts)

            if not cm.file_exists(path=path):
