                )
                error = BadRequest('Header "{0}" malformed.'.format(ex.header))
                return error.wsgi_response(environ, start_response)


        if clear_untrusted:
            clear_untrusted_headers(
                environ, untrusted_headers, log_warning=log_untrusted, logger=logger,
            )

