        self._preload()
    def is_same_as(self, other):

        res = False
        try:
            res = self._configfile == other._configfile
        except Exception as e:
            pass
        return res
    def pidfile(self):
        with self.lock:
            return self._pidfile
    def save_thread(self):
        with self.lock:
