        """
        with self.engine.connect() as conn:


            reult = conn.execute(_REPOS.select())
            for row in reult:
                if row['repopath'].startswith('/') or row['repopath'].endswith('/'):
                    conn.execute(
                        _REPOS.update()
                        .where(_REPOS.c.repoid == row['repoid'])
                        .values(repopath=row['repopath'].strip('/'))
