            prev_repo = (None, None)
            for row in reult:
                if prev_repo[0] == row['userid'] and (
                    prev_repo[1] == row['repopath'] or row['repopath'].startswith(prev_repo[1] + '/')
                ):
                    conn.execute(_REPOS.delete(_REPOS.c.repoid == row['repoid']))
                else:
                    prev_repo = (row['userid'], row['repopath'])
