        self.bus.publish('user_added', userobj)

        return userobj
class RdiffRepo(object):
    def __init__(self, user_root, path, encoding):
        if isinstance(user_root, str):
            user_root = os.fsencode(user_root)
        if isinstance(path, str):
            path = os.fsencode(path)
        assert isinstance(user_root, bytes)
        assert isinstance(path, bytes)
        assert encoding
        self._encoding = encodings.search_function(encoding)
        assert self._encoding
        self.path = path.strip(b"/")
        if self.path:
            self.full_path = os.path.normpath(os.path.join(user_root, self.path))
        else:
            self.full_path = os.path.normpath(user_root)


        self._data_path = os.path.join(self.full_path, RDIFF_BACKUP_DATA)
        assert isinstance(self._data_path, bytes)
        self._increment_path = os.path.join(self._data_path, INCREMENTS)
        self.current_mirror = MetadataDict(self, CurrentMirrorEntry)
        self.error_log = MetadataDict(self, LogEntry)
        self.mirror_metadata = MetadataDict(self, MirrorMetadataEntry)
        self.file_statistics = MetadataDict(self, FileStatisticsEntry)
        self.session_statistics = MetadataDict(self, SessionStatisticsEntry)
    def backup_dates(self):
        """Return a list of dates when backup was executed. This list is
        sorted from old to new (ascending order). To identify dates,
        'mirror_metadata' file located in rdiff-backup-data are used."""
        return self.mirror_metadata.keys()
    def backup_log(self):
        """
        Return the location of the backup log.
        """
        return BackupLogEntry(self, b'backup.log')
    def delete(self, path):
        """
        Delete this entry from the repository history using rdiff-backup-delete.
        """
        path_obj = self.fstat(path)
        if path_obj.isroot:
            return self.delete_repo()

        rdiff_backup_delete = find_rdiff_backup_delete()
        cmdline = [rdiff_backup_delete, path_obj.full_path]
        logger.info('executing: %r' % cmdline)
        process = subprocess.Popen(cmdline, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env={'LANG': LANG})
        for line in process.stdout:
            line = line.rstrip(b'\n').decode('utf-8', errors='replace')
            logger.info('rdiff-backup-delete: %s' % line)
        retcode = process.wait()
        if retcode:
            raise CalledProcessError(retcode, cmdline)
    def delete_repo(self):
        """Delete the repository permanently."""


        def handle_error(func, path, exc_info):
            if exc_info[0] == PermissionError:

                if not os.access(os.path.dirname(path), os.W_OK | os.R_OK | os.X_OK):
                    os.chmod(os.path.dirname(path), 0o0700)
                if not os.access(path, os.W_OK | os.R_OK):
                    os.chmod(path, 0o0600)
                if os.path.isdir(path):
                    return shutil.rmtree(path, onerror=handle_error)
                else:
                    return os.unlink(path)
            raise

        try:
            shutil.rmtree(self.full_path, onerror=handle_error)
        except Exception:
            logger.warning('fail to delete repo', exc_info=1)
    def display_name(self):
        """Return the most human representation of the repository name."""
        return self.get_display_name(b'')
    def _decode(self, value, errors='replace'):
        """Used to decode a repository path into unicode."""
        assert isinstance(value, bytes)
        return self._encoding.decode(value, errors)[0]
    def _entries(self):
        return sorted(os.listdir(self._data_path))
    def listdir(self, path):
        """
        Return a list of RdiffDirEntry each representing a file or a folder in the given path.
        """

        full_path = os.path.realpath(os.path.join(self.full_path, path.strip(b'/')))
        relative_path = os.path.relpath(full_path, self.full_path)
        if relative_path.startswith(RDIFF_BACKUP_DATA):
            raise DoesNotExistError(path)
        increment_path = os.path.normpath(os.path.join(self._increment_path, relative_path))
        if not full_path.startswith(self.full_path) or not increment_path.startswith(self.full_path):
            raise AccessDeniedError('%s make reference outside the repository' % self._decode(path))


        try:
            existing_items = os.listdir(full_path)
            if relative_path == b'.':
                existing_items.remove(RDIFF_BACKUP_DATA)
        except (NotADirectoryError, FileNotFoundError):
            existing_items = None
        except OSError:
            raise AccessDeniedError(path)
        try:
            increment_items = os.listdir(increment_path)
        except (NotADirectoryError, FileNotFoundError):
            increment_items = None
        except OSError:
            raise AccessDeniedError(path)

        if existing_items is None and increment_items is None:
            raise DoesNotExistError(path)



        entries = {}
        for name in existing_items or []:
            entries[name] = RdiffDirEntry(
                self,
                os.path.normpath(os.path.join(relative_path, name)),
                exists=True,
                increments=[],
            )
        for item in increment_items or []:
            try:
                increment = IncrementEntry(item)
            except ValueError:

                continue
            entry = entries.get(increment.name, None)
            if not entry:

                entry = entries[increment.name] = RdiffDirEntry(
                    self,
                    os.path.normpath(os.path.join(relative_path, increment.name)),
                    exists=False,
                    increments=[increment] if increment else [],
                )
            else:

                bisect.insort_left(entry._increments, increment)
        return sorted(list(entries.values()), key=lambda e: e.path)
    def fstat(self, path):
        """Return a new instance of DirEntry to represent the given path."""

        assert isinstance(path, bytes)
        full_path = os.path.normpath(os.path.join(self.full_path, path.strip(b'/')))
        increment_path = os.path.normpath(os.path.join(self._increment_path, path.strip(b'/'), b'..'))
        if not full_path.startswith(self.full_path) or not increment_path.startswith(self.full_path):
            raise AccessDeniedError('%s make reference outside the repository' % self._decode(path))
        relative_path = os.path.relpath(full_path, self.full_path)
        if relative_path.startswith(RDIFF_BACKUP_DATA):
            raise DoesNotExistError(path)

        if relative_path == b'.':
            return RdiffDirEntry(self, b'', True, [])


        try:
            os.lstat(full_path)
            exists = True
        except (OSError, ValueError):
            exists = False


        increment_items = os.listdir(increment_path)


        prefix = os.path.basename(full_path)
        entry = RdiffDirEntry(self, relative_path, exists, [])
        for item in increment_items:
            if not item.startswith(prefix):

                continue
            try:
                increment = IncrementEntry(item)
            except ValueError:

                continue
            if increment.name != prefix:

                continue

            bisect.insort_left(entry._increments, increment)


        if not exists and not entry._increments:
            logger.error("path [%r] doesn't exists", path)
            raise DoesNotExistError(path)


        return entry
    def last_backup_date(self):
        """Return the last known backup dates."""
        try:
            if len(self.current_mirror) > 0:
                return self.current_mirror[-1].date
            return None
        except (PermissionError, FileNotFoundError):
            return None
    def get_display_name(self, path):
        """
        Return proper display name of the given path according to repository encoding and quoted characters.
        """
        assert isinstance(path, bytes)
        path = path.strip(b'/')
        if path in [b'.', b'']:

            if not self.path:
                return self._decode(unquote(os.path.basename(self.full_path)))
            return self._decode(unquote(self.path))
        else:

            return self._decode(unquote(os.path.basename(path)))
    def remove_older(self, remove_older_than):
        logger.info("execute rdiff-backup --force --remove-older-than=%sD %r", remove_older_than, self.full_path)
        subprocess.call(
            [
                b'rdiff-backup',
                b'--force',
                b'--remove-older-than=' + str(remove_older_than).encode(encoding='latin1') + b'D',
                self.full_path,
            ]
        )
    def restore(self, path, restore_as_of, kind=None):
        """
        Restore the current directory entry into a fileobj containing the
        file content of the directory compressed into an archive.

        `kind` must be one of the supported archive type or none to use `zip` for folder and `raw` for file.

        Return a filename and a fileobj.
        """
        assert isinstance(path, bytes)
        assert restore_as_of, "restore_as_of must be defined"
        assert kind in ['tar', 'tar.bz2', 'tar.gz', 'tbz2', 'tgz', 'zip', 'raw', None]


        path_obj = self.fstat(path)
        if path_obj.isdir:
            if kind == 'raw':
                raise ValueError('raw type not supported for directory')
            kind = kind or 'zip'
        else:
            kind = kind or 'raw'


        if kind == 'raw':
            filename = path_obj.display_name
        else:
            filename = "%s.%s" % (path_obj.display_name, kind)



        cmdline = [
            os.fsencode(sys.executable),
            b'-m',
            b'rdiffweb.core.restore',
            b'--restore-as-of',
            str(restore_as_of).encode('latin'),
            b'--encoding',
            self._encoding.name.encode('latin'),
            b'--kind',
            kind.encode('latin'),
            os.path.join(self.full_path, unquote(path_obj.path)),
            b'-',
        ]
        proc = subprocess.Popen(
            cmdline,
            shell=False,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=None,
        )


        output = b''
        success = False
        line = proc.stderr.readline()
        while line:
            output += line
            if b'Starting restore of' in line:
                success = True
                break
            line = proc.stderr.readline()
        if not success:
            raise CalledProcessError(1, cmdline, output)

        t = threading.Thread(target=_readerthread, args=(proc.stderr, logger.debug))
        t.daemon = True
        t.start()
        return filename, _wrap_close(proc.stdout, proc)
    def restore_log(self):
        """
        Return the location of the restore log.
        """
        return RestoreLogEntry(self, b'restore.log')
    def status(self):
        """Check if a backup is in progress for the current repo."""


        try:

            for current_mirror in self.current_mirror:
                pid = current_mirror.extract_pid()
                try:
                    p = psutil.Process(pid)
                    if any('rdiff-backup' in c for c in p.cmdline()):
                        return ('in_progress', _('A backup is currently in progress to this repository.'))
                except psutil.NoSuchProcess:
                    logger.debug('pid [%s] does not exists', pid)




            if len(self.current_mirror) > 1 or len(self.current_mirror) == 0:
                self._status = ('interrupted', _('The previous backup seams to have failed.'))
                return self._status
        except FileNotFoundError:
            self._entries = []
            return ('failed', _('The repository cannot be found or is badly damaged.'))
        except PermissionError:
            self._entries = []
            logger.warning('error reading current_mirror files', exc_info=1)
            return ('failed', _("Permissions denied. Contact administrator to check repository's permissions."))

        return ('ok', '')
            self.panels = [PrefsGeneralPanelProvider(), NotificationPref()]
                self.panels += [SSHKeysPlugin()]

class SSHbase(Bcfg2.Server.Plugin.Plugin,
              Bcfg2.Server.Plugin.Generator,
              Bcfg2.Server.Plugin.DirectoryBacked,
              Bcfg2.Server.Plugin.PullTarget):
    name = 'SSHbase'
    __version__ = '$Id$'
    __author__ = 'bcfg-dev@mcs.anl.gov'
    pubkeys = ["ssh_host_dsa_key.pub.H_%s",
    hostkeys = ["ssh_host_dsa_key.H_%s",
    keypatterns = ['ssh_host_dsa_key', 'ssh_host_rsa_key', 'ssh_host_key',
    def __init__(self, core, datastore):
        Bcfg2.Server.Plugin.Plugin.__init__(self, core, datastore)
        Bcfg2.Server.Plugin.Generator.__init__(self)
        Bcfg2.Server.Plugin.PullTarget.__init__(self)
        try:
            Bcfg2.Server.Plugin.DirectoryBacked.__init__(self, self.data,
                                                         self.core.fam)
        except OSError, ioerr:
            self.logger.error("Failed to load SSHbase repository from %s" \
                              % (self.data))
            self.logger.error(ioerr)
            raise Bcfg2.Server.Plugin.PluginInitError
        self.Entries = {'Path':
                        {'/etc/ssh/ssh_known_hosts': self.build_skn,
                         '/etc/ssh/ssh_host_dsa_key': self.build_hk,
                         '/etc/ssh/ssh_host_rsa_key': self.build_hk,
                         '/etc/ssh/ssh_host_dsa_key.pub': self.build_hk,
                         '/etc/ssh/ssh_host_rsa_key.pub': self.build_hk,
                         '/etc/ssh/ssh_host_key': self.build_hk,
                         '/etc/ssh/ssh_host_key.pub': self.build_hk}}
        self.ipcache = {}
        self.namecache = {}
        self.__skn = False
    def get_skn(self):
        """Build memory cache of the ssh known hosts file."""
        if not self.__skn:
            self.__skn = "\n".join([value.data for key, value in \
                                    self.entries.iteritems() if \
                                    key.endswith('.static')])
            names = dict()

            if len(self.core.metadata.query.all()) == 0:
                self.__skn = False
                return self.__skn
            for cmeta in self.core.metadata.query.all():
                names[cmeta.hostname] = set([cmeta.hostname])
                names[cmeta.hostname].update(cmeta.aliases)
                newnames = set()
                newips = set()
                for name in names[cmeta.hostname]:
                    newnames.add(name.split('.')[0])
                    try:
                        newips.add(self.get_ipcache_entry(name)[0])
                    except:
                        continue
                names[cmeta.hostname].update(newnames)
                names[cmeta.hostname].update(cmeta.addresses)
                names[cmeta.hostname].update(newips)

                if True:
                    for ip in newips:
                        try:
                            names[cmeta.hostname].update(self.get_namecache_entry(ip))
                        except:
                            continue
                names[cmeta.hostname] = sorted(names[cmeta.hostname])

            pubkeys = [pubk for pubk in self.entries.keys() \
                       if pubk.find('.pub.H_') != -1]
            pubkeys.sort()
            badnames = set()
            for pubkey in pubkeys:
                hostname = pubkey.split('H_')[1]
                if hostname not in names:
                    if hostname not in badnames:
                        badnames.add(hostname)
                        self.logger.error("SSHbase: Unknown host %s; ignoring public keys" % hostname)
                    continue
                self.__skn += "%s %s" % (','.join(names[hostname]),
                                         self.entries[pubkey].data)
        return self.__skn
    def set_skn(self, value):
        """Set backing data for skn."""
        self.__skn = value
    skn = property(get_skn, set_skn)
    def HandleEvent(self, event=None):
        """Local event handler that does skn regen on pubkey change."""
        Bcfg2.Server.Plugin.DirectoryBacked.HandleEvent(self, event)
        if event and '_key.pub.H_' in event.filename:
            self.skn = False
        if event and event.filename.endswith('.static'):
            self.skn = False
        if not self.__skn:
            if (len(self.entries.keys())) >= (len(os.listdir(self.data))-1):
                _ = self.skn
    def HandlesEntry(self, entry, _):
        """Handle key entries dynamically."""
        return entry.tag == 'Path' and \
               ([fpat for fpat in self.keypatterns
                 if entry.get('name').endswith(fpat)]
                or entry.get('name').endswith('ssh_known_hosts'))
    def HandleEntry(self, entry, metadata):
        """Bind data."""
        if entry.get('name').endswith('ssh_known_hosts'):
            return self.build_skn(entry, metadata)
        else:
            return self.build_hk(entry, metadata)
    def get_ipcache_entry(self, client):
        """Build a cache of dns results."""
        if client in self.ipcache:
            if self.ipcache[client]:
                return self.ipcache[client]
            else:
                raise socket.gaierror
        else:

            try:
                ipaddr = socket.gethostbyname(client)
                self.ipcache[client] = (ipaddr, client)
                return (ipaddr, client)
            except socket.gaierror:
                cmd = "getent hosts %s" % client
                ipaddr = Popen(cmd, shell=True, \
                               stdout=PIPE).stdout.read().strip().split()
                if ipaddr:
                    self.ipcache[client] = (ipaddr, client)
                    return (ipaddr, client)
                self.ipcache[client] = False
                self.logger.error("Failed to find IP address for %s" % client)
                raise socket.gaierror
    def get_namecache_entry(self, cip):
        """Build a cache of name lookups from client IP addresses."""
        if cip in self.namecache:

            if self.namecache[cip]:
                return self.namecache[cip]
            else:
                raise socket.gaierror
        else:

            try:
                rvlookup = socket.gethostbyaddr(cip)
                if rvlookup[0]:
                    self.namecache[cip] = [rvlookup[0]]
                else:
                    self.namecache[cip] = []
                self.namecache[cip].extend(rvlookup[1])
                return self.namecache[cip]
            except socket.gaierror:
                self.namecache[cip] = False
                self.logger.error("Failed to find any names associated with IP address %s" % cip)
                raise
    def build_skn(self, entry, metadata):
        """This function builds builds a host specific known_hosts file."""
        client = metadata.hostname
        entry.text = self.skn
        hostkeys = [keytmpl % client for keytmpl in self.pubkeys \
                        if (keytmpl % client) in self.entries]
        hostkeys.sort()
        for hostkey in hostkeys:
            entry.text += "localhost,localhost.localdomain,127.0.0.1 %s" % (
                self.entries[hostkey].data)
        permdata = {'owner':'root',
                    'group':'root',
                    'type':'file',
                    'perms':'0644'}
        [entry.attrib.__setitem__(key, permdata[key]) for key in permdata]
    def build_hk(self, entry, metadata):
        """This binds host key data into entries."""
        client = metadata.hostname
        filename = "%s.H_%s" % (entry.get('name').split('/')[-1], client)
        if filename not in self.entries.keys():
            self.GenerateHostKeys(client)
        if not filename in self.entries:
            self.logger.error("%s still not registered" % filename)
            raise Bcfg2.Server.Plugin.PluginExecutionError
        keydata = self.entries[filename].data
        permdata = {'owner':'root',
                    'group':'root',
                    'type':'file',
                    'perms':'0600'}
        if entry.get('name')[-4:] == '.pub':
            permdata['perms'] = '0644'
        [entry.attrib.__setitem__(key, permdata[key]) for key in permdata]
        if "ssh_host_key.H_" == filename[:15]:
            entry.attrib['encoding'] = 'base64'
            entry.text = binascii.b2a_base64(keydata)
        else:
            entry.text = keydata
    def GenerateHostKeys(self, client):
        """Generate new host keys for client."""
        keylist = [keytmpl % client for keytmpl in self.hostkeys]
        for hostkey in keylist:
            if 'ssh_host_rsa_key.H_' == hostkey[:19]:
                keytype = 'rsa'
            elif 'ssh_host_dsa_key.H_' == hostkey[:19]:
                keytype = 'dsa'
            else:
                keytype = 'rsa1'

            if hostkey not in self.entries.keys():
                fileloc = "%s/%s" % (self.data, hostkey)
                publoc = self.data + '/' + ".".join([hostkey.split('.')[0],
                                                     'pub',
                                                     "H_%s" % client])
                tempdir = tempfile.mkdtemp()
                temploc = "%s/%s" % (tempdir, hostkey)
                cmd = 'ssh-keygen -q -f %s -N "" -t %s -C root@%s < /dev/null'
                os.system(cmd % (temploc, keytype, client))
                shutil.copy(temploc, fileloc)
                shutil.copy("%s.pub" % temploc, publoc)
                self.AddEntry(hostkey)
                self.AddEntry(".".join([hostkey.split('.')[0]]+['pub', "H_%s" \
                                                                % client]))
                try:
                    os.unlink(temploc)
                    os.unlink("%s.pub" % temploc)
                    os.rmdir(tempdir)
                except OSError:
                    self.logger.error("Failed to unlink temporary ssh keys")
    def AcceptChoices(self, _, metadata):
        return [Bcfg2.Server.Plugin.Specificity(hostname=metadata.hostname)]
    def AcceptPullData(self, specific, entry, log):
        """Per-plugin bcfg2-admin pull support."""

        filename = "%s/%s.H_%s" % (self.data, entry['name'].split('/')[-1],
                                   specific.hostname)
        open(filename, 'w').write(entry['text'])
        if log:
            print "Wrote file %s" % filename
